  "settings.themeVars": "Couleurs du thème",
  "settings.themeVars.help": "Recolorer le thème actif variable par variable — surfaces, texte, bordures, l’accent, teintes d’état — dans une fenêtre à part, avec le style des coins. Les remplacements s’appliquent à tous les thèmes, pas seulement à celui-ci.",
  "settings.themeVars.open": "Personnaliser…",
  "theme.title": "Couleurs du thème",
  "theme.intro": "Chaque valeur ici remplace le jeton du thème actif — sur ce thème comme sur tous les autres — jusqu’à sa réinitialisation. Les couleurs s’écrivent #rrggbb, ou #rrggbbaa là où une valeur doit rester translucide.",
  "theme.reset": "Tout réinitialiser",
  "theme.resetOne": "Revenir à la valeur du thème",
  "theme.overridden": "{n} remplacées",
  "theme.none": "Rien de remplacé",
  "theme.presets": "Thèmes enregistrés",
  "theme.presets.help":
    "Met tout l'aspect de côté sous un nom — thème de base, accent, chaque couleur modifiée ici et le style des coins — pour y revenir plus tard ou garder deux palettes en parallèle.",
  "theme.presets.name": "Nommer cet aspect",
  "theme.presets.save": "Enregistrer l'actuel",
  "theme.presets.replace": "Remplace le thème enregistré portant le même nom",
  "theme.presets.full": "La liste est pleine — {n} thèmes enregistrés. Supprimez-en un d'abord.",
  "theme.presets.none":
    "Rien d'enregistré pour l'instant. Nommez l'aspect actuel et il apparaîtra ici.",
  "theme.presets.load": "Charger",
  "theme.presets.loadHelp": "Appliquer cet aspect — thème de base, accent, couleurs et coins",
  "theme.presets.update": "Écraser avec l'aspect actuel",
  "theme.presets.delete": "Supprimer",
  "theme.presets.confirm": "Supprimer ?",
  "theme.presets.meta": "{theme} · {n} couleurs",
  "theme.presets.metaPlain": "{theme} · couleurs du thème inchangées",
  "theme.palette": "Couleurs de ce thème",
  "theme.palette.pick": "Choisir parmi les couleurs déjà utilisées par ce thème",
  "theme.group.surfaces": "Surfaces",
  "theme.group.surfaces.help": "La fenêtre, ses panneaux et les en-têtes posés dessus — les barres d’onglets des sous-fenêtres et les en-têtes du panneau de fichiers, qui partagent une seconde surface. La barre du haut de l’application suit --bg-header d’ici jusqu’à ce que vous lui donniez un fond propre dans « Barre du haut », plus bas.",
  "theme.group.topframe": "Barre du haut",
  "theme.group.topframe.help": "La barre de titre de {app} — le bandeau qui porte l’horloge, les pastilles de projet et les boutons de fenêtre. Trois couches la composent : un fond, un voile d’accent par-dessus, et la couture en dessous qui dit où s’arrête le chrome de l’application et où commence son contenu. Chacune suit un token partagé tant que vous ne la fixez pas : la barre se retonalise sans que l’accent bouge dans tout le reste de la fenêtre. Les trois niveaux de texte ci-dessous sont réaffectés à tout le sous-arbre de la barre : une valeur déplace d’un coup chacun de ses libellés — les menus qui en sortent gardent l’encre du thème.",
  "theme.group.subwindow": "Sous-fenêtres",
  "theme.group.subwindow.help": "L’en-tête propre d’une sous-fenêtre — la barre d’onglets au-dessus de chaque volet — plus les deux repères qui disent quelle sous-fenêtre a le focus. La barre partage la seconde surface de chrome de l’application avec tous les en-têtes du panneau de fichiers, et ses repères lisent l’accent nu : rien de tout cela ne pouvait bouger séparément. Fixez ici un niveau de texte et toute la barre suit : libellés d’onglets, poignée, chevrons, pastilles.",
  "theme.group.sidepanel": "Panneau latéral",
  "theme.group.sidepanel.help": "Le panneau de fichiers qui glisse depuis le bord, à lui seul. Chaque valeur ici suit le jeton partagé qu’elle lirait autrement : le panneau ne se détache du reste de la fenêtre qu’une fois que vous en fixez un — et ses en-têtes bougent sans emmener les barres d’onglets des sous-fenêtres.",
  "theme.group.alerts": "Bandeau d’alertes",
  "theme.group.alerts.help": "Le groupe d’alertes sous l’arborescence — courrier urgent, prochains rendez-vous, cartes à échéance. Son apparence découle de l’accent, du fond de la fenêtre et des teintes d’état ; ces valeurs sont cette dérivation, si bien que le bandeau se retonne sans déplacer ce à quoi il emprunte.",
  "theme.group.text": "Texte",
  "theme.group.text.help": "Les trois niveaux de texte, du plus clair au plus discret.",
  "theme.group.borders": "Bordures",
