  "settings.language.help":
    "Définit la langue de l'interface de {app}. Effet immédiat — aucun redémarrage.",
  "settings.runScriptsBg": "Exécuter les scripts en arrière-plan",
  "settings.showUntestedTags": "Afficher les étiquettes « non testé »",
  "settings.showUntestedTags.help": "Affiche les étiquettes des fonctions qui n’ont pas encore été vérifiées dans l’application en cours d’exécution.",
  "settings.claudeRemote": "Contrôle à distance de Claude",
  "mcpSecurity.title": "Accès des sessions MCP",
  "mcpSecurity.help": "Les autorisations ne concernent que cette session en cours. Les nouvelles sessions racine gardent les valeurs par défaut ; les lecteurs de courrier commencent avec le courrier seulement. Désactiver l'écriture donne un accès en lecture seule. Les données partagées avec un agent ayant accès au réseau peuvent quitter cet ordinateur. Les écritures restreintes du calendrier et du tableau exigent toujours une revue. La révocation est définitive pour l'onglet : son agent est refusé dès lors, et seule la réouverture de l'onglet délivre un nouveau jeton.",
  "mcpSecurity.refresh": "Actualiser",
  "mcpSecurity.empty": "Aucune session MCP active.",
  "mcpSecurity.headless": "Les onglets que {app} Mobile a lancés sans fenêtre ouverte reçoivent leurs outils de planification, de push et d'aide du service d'arrière-plan Mobile, pas de cette fenêtre. Leurs sessions ne sont pas listées ici. Elles prennent fin à la fermeture de l'onglet ou à l'arrêt du service. Leurs demandes de push et de release sont refusées jusqu'à ce que l'onglet soit relancé depuis cette fenêtre.",
  "mcpSecurity.write": "Autoriser les modifications de calendriers, tableaux et brouillons",
  "mcpSecurity.revoke": "Révoquer l’accès",
  "mcpSecurity.all": "Tous, y compris les futures entrées",
  "mcpSecurity.calendars": "Calendriers visibles",
  "mcpSecurity.projects": "Projets et cartes visibles",
  "mcpSecurity.accounts": "Comptes de courrier visibles (le consentement du compte reste requis)",
  "mcpSecurity.unassigned": "Cartes sans projet",
  "mcpSecurity.family.calendar": "Outils de calendrier",
  "mcpSecurity.family.board": "Outils du tableau",
  "mcpSecurity.family.projects": "Résumés des projets",
  "mcpSecurity.family.mail": "Outils de courrier",
  "mcpSecurity.agent": "Agent racine",
  "mcpSecurity.local_model": "Modèle local",
  "mcpSecurity.reader": "Lecteur de courrier",
  "mcpSecurity.audit": "Activité MCP récente",
  "mcpSecurity.auditHelp": "Les 50 derniers enregistrements parmi 500 au plus, gardés en mémoire pour cette exécution. Ils contiennent la session, l'outil, la décision, la durée et une catégorie de motif fixe (pour une session de planification, aussi la cible), sans identifiants, arguments ni corps de messages. Les requêtes refusées avant authentification apparaissent en « Aucune session », avec leur propre limite. Un enregistrement appartient au jeton de l'onglet : tout ce que l'agent lance dans cet onglet (un hook, un script, une compilation) hérite du jeton et peut appeler les outils au nom de l'onglet ; un enregistrement est donc celui de l'onglet, pas nécessairement un appel de l'agent lui-même.",
  "mcpSecurity.time": "Heure",
  "mcpSecurity.caller": "Session",
  "mcpSecurity.tool": "Outil",
  "mcpSecurity.outcome": "Résultat",
  "mcpSecurity.allowed": "Autorisé",
  "mcpSecurity.denied": "Accès refusé",
  "mcpSecurity.refused": "Requête refusée",
  "mcpSecurity.protocol": "Requête de protocole",
  "mcpSecurity.reason": "Détail",
  "mcpSecurity.unauthenticated": "Aucune session",
  "mcpSecurity.admission": "Refusée avant authentification",
  "mcpSecurity.target": "cible {target}",
  "mcpSecurity.revokeTitle": "Révoquer l'accès MCP de cet onglet ?",
  "mcpSecurity.revokeBody": "« {tab} » perd définitivement les outils de {app} : son agent est refusé dès maintenant, et seule la réouverture de l'onglet délivre un nouveau jeton.",
  "mcpSecurity.reviewScope": "Accès de session : {calendars} calendriers, {projects} projets ; appelant : {caller}",
  "mcpSecurity.allScopes": "tous",
  "rootReview.title": "Propositions d’agents",
  "rootReview.badge": "✓ Approbations",
  "rootReview.badgeHint": "Les propositions des agents en attente de décision. Cliquez pour voir les lignes ; le nombre est ce qui reste en attente.",
