  "mobile.title": "{app} Mobile",
  "mobile.mailWrites": "Courrier depuis le téléphone",
  "mobile.mailRead": "Lire le courrier sur le téléphone",
  "mobile.mailReadHelp": "Un téléphone appairé peut lister vos comptes et dossiers de courrier et ouvrir les messages. Désactivé, la vue courrier du téléphone est entièrement refusée, marquage et réponse compris.",
  "mobile.mailActions": "Marquer comme lu et étoiler depuis le téléphone",
  "mobile.mailActionsHelp": "Un téléphone appairé peut marquer un message comme lu ou non lu et poser ou retirer son étoile. Le bureau applique le drapeau via sa propre session de courrier et répond avec la liste actualisée. Supprimer et déplacer restent sur le bureau, où ils peuvent être annulés.",
  "mobile.mailReply": "Répondre depuis le téléphone",
  "mobile.mailReplyHelp": "Un téléphone appairé peut envoyer une réponse en texte brut à un message qu'il est en train de lire. Le téléphone ne fournit que le texte : le destinataire, l'objet et le fil proviennent du message d'origine, si bien qu'un téléphone ne peut répondre qu'aux personnes qui vous ont déjà écrit. Pas de nouveau courrier, pas de pièces jointes, ni signature ni chiffrement. Un téléphone perdu avec ce réglage actif peut envoyer du courrier en votre nom jusqu'à sa révocation.",
  "mobile.settingsHelp": "Accès privé aux terminaux de projet via Tailscale Serve. L'hôte n'écoute que sur le loopback et chaque navigateur doit être appairé. Il tourne tant que {app} tourne : démarré avec l'application, arrêté à sa fermeture.",
  "mobile.healthOffTitle": "Mobile est désactivé",
  "mobile.healthOffDetail": "Aucun hôte {app} Mobile n'est actuellement publié.",
  "mobile.healthStoppedTitle": "L'hôte est arrêté",
  "mobile.healthStoppedDetail": "Mobile est activé dans les réglages mais ne sert rien ; ne le démarrez qu'après avoir vérifié le mappage Serve privé.",
  "mobile.healthServeTitle": "Le mappage Serve demande votre attention",
  "mobile.healthServeDetail": "{app} ne peut pas vérifier actuellement son mappage HTTPS loopback privé exact.",
  "mobile.healthGoodTitle": "Publication privée vérifiée",
  "mobile.healthGoodDetail": "L'hôte est limité au loopback et la route Tailscale Serve configurée est en HTTPS privé.",
  "mobile.lockdownNow": "Verrouiller maintenant",
  "mobile.lockdownTitle": "Révoquer tous les appareils appairés et arrêter l'hôte",
  "mobile.lockdownTitleStopped": "L'hôte est déjà arrêté",
  "mobile.lockdownConfirm": "Verrouiller {app} Mobile maintenant ? Cela révoque immédiatement chaque téléphone appairé, ferme leurs connexions de terminal et arrête l'hôte Mobile. Chaque téléphone devra s'appairer à nouveau.",
  "mobile.lockdownPartial": "Le verrouillage n'a été que partiellement effectué : {reason}",
  "mobile.scopeHelp": "Ceci vérifie la forme de publication de {app}, pas vos ACL du tailnet, la MFA du compte, Tailnet Lock ni le verrouillage d'écran du téléphone. Configurez-les dans Tailscale et sur le téléphone.",
  "mobile.phoneInstallTitle": "Installer {app} Mobile sur votre téléphone",
  "mobile.phoneInstallHelp": "Vérifie le mappage Tailscale Serve privé, puis affiche l'URL de confiance et un code QR à scanner dans un terminal racine. Cela n'active pas Mobile et ne modifie pas votre configuration Tailscale.",
  "mobile.phoneInstallButton": "Afficher le QR d'installation",
  "mobile.phoneInstallTab": "Installer {app} Mobile sur le téléphone",
  "mobile.phoneInstallToast": "La passation d'installation vers le téléphone s'exécute dans le terminal racine",
  "mobile.phoneInstallError": "Impossible d'ouvrir la passation d'installation vers le téléphone : {reason}",
  "mobile.guideSummary": "Configurer Tailscale Serve",
  "mobile.windowsTerminalsNote": "Sous Windows, le téléphone ne peut pas ouvrir les terminaux ni les onglets d'agents de cet ordinateur : ils passent par tmux, que Windows n'a pas.",
  "mobile.guideIntro": "Faites ceci sur cet ordinateur avant d'activer {app} Mobile. Installez Tailscale et connectez-vous ici, puis installez-le et connectez-vous au même tailnet sur le téléphone ou la tablette qui utilisera Mobile.",
  "mobile.guideStep1a": "Dans un terminal de cet ordinateur, inspectez la publication existante avec",
  "mobile.guideStep1b": ". {app} Mobile a besoin du gestionnaire HTTPS / (racine) ; ne remplacez donc un gestionnaire racine existant que si vous voulez vraiment déplacer ce service.",
  "mobile.guideStep2a": "Configurez le proxy inverse privé et persistant. Utilisez Serve — pas Funnel :",
  "mobile.guideStep2b": "Si Tailscale demande une approbation ou la configuration HTTPS, terminez-la dans le navigateur qu'il ouvre.",
  "mobile.guideStep3a": "Exécutez",
  "mobile.guideStep3b": "à nouveau, puis utilisez",
  "mobile.guideStep3c": "ci-dessous. {app} remplit le nom de l'ordinateur, le port loopback et l'origine vérifiée à partir du mappage racine privé.",
  "mobile.guideStep4a": "Activez {app} Mobile. {app} vérifie que le gestionnaire racine de l'origine redirige exactement vers",
  "mobile.guideStep4b": " ; utilisez",
  "mobile.guideStep4c": "si vous avez modifié Tailscale dans un autre terminal.",
  "mobile.guideStep5": "Activez les projets locaux à exposer, créez un code d'appairage, puis ouvrez l'origine vérifiée sur le téléphone ou la tablette et saisissez ce code.",
  "mobile.guideOutro": "L'adresse n'est joignable que par les appareils autorisés dans votre tailnet, et Mobile exige en plus son propre appairage d'appareils. N'utilisez pas Tailscale Funnel : il rend le service public et {app} refusera de démarrer.",
  "mobile.setUpInTerminal": "Configurer dans le terminal",
  "mobile.setUpInTerminalHelp": "Ouvre un terminal racine et exécute la commande ci-dessus après confirmation.",
  "mobile.setUpConfirm": "Ceci va ouvrir un terminal racine et exécuter :\n\n{command}\n\nCela met à jour le gestionnaire racine HTTPS de Tailscale Serve et peut remplacer un service actuellement monté sur /. Continuer ?",
