  "mobile.tunnel.step.forceStop": "Déjà connecté ? Forcez son arrêt : Paramètres → Applications → Tailscale → Forcer l'arrêt, puis rouvrez-le. Après un changement de réseau, il peut se dire connecté sans rien transmettre ; le désactiver puis le réactiver n'y change rien.",
