  "mobile.indDeviceLastSeen": "Dernière connexion {when}",
  "mobile.indDeviceNeverSeen": "Jamais connecté",
  "mobile.indDisconnect": "Déconnecter",
  "mobile.indDisconnectConfirm": "Déconnecter ?",
  "mobile.indDisconnectHint": "Désappaire cet appareil et le déconnecte en quelques secondes. Il lui faudra un nouveau code d'appairage pour revenir.",
  "mobile.indDisconnectError": "Impossible de déconnecter {name} : {reason}",
  "mobile.indSetUpTitle": "{app} Mobile n'est pas configuré",
  "mobile.setupTitle": "Configurer {app} Mobile",
  "mobile.indDeviceAccess": "Accès",
  "mobile.indDeviceAccessHint": "Choisir les sections et projets que voit {name}",
  "mobile.setupIntro": "{app} Mobile amène les projets, terminaux et agents de cet ordinateur sur votre téléphone. Tout passe par votre propre réseau Tailscale privé : rien n'est publié sur internet, et le téléphone doit toujours être appairé.",
  "mobile.setupStep1Title": "Installer Tailscale sur cet ordinateur",
  "mobile.setupStep1Body": "Installez Tailscale ici et connectez-vous. C'est lui qui porte la connexion du téléphone — {app} n'écoute que sur la boucle locale.",
  "mobile.setupStep2Title": "Installer Tailscale sur le téléphone",
  "mobile.setupStep2Body": "Installez l'application Tailscale sur le téléphone ou la tablette et connectez-vous au même tailnet que cet ordinateur.",
  "mobile.setupStep3Title": "Publier {app} en privé",
  "mobile.setupStep3Body": "Dirigez Tailscale Serve vers le port loopback de {app}. Utilisez Serve, jamais Funnel : Funnel rendrait le service public et {app} refuserait de démarrer. Si Tailscale demande une approbation ou la configuration HTTPS, terminez-la dans le navigateur qu'il ouvre.",
  "mobile.setupStep4Title": "Activer {app} Mobile",
  "mobile.setupStep4Body": "Dans Paramètres → Mobile, appuyez sur « Détecter les réglages de Tailscale Serve », vérifiez le nom de l'ordinateur, le port et l'origine remplis, puis activez {app} Mobile. {app} vérifie la correspondance avant de démarrer l'hôte.",
  "mobile.setupStep5Title": "Choisir ce que le téléphone peut ouvrir",
  "mobile.setupStep5Body": "Sous « Accès par projet », dans ces mêmes réglages, activez les projets et les boîtes que le téléphone peut ouvrir. Tout est désactivé tant que vous ne l'activez pas.",
  "mobile.setupStep6Title": "Appairer le téléphone",
  "mobile.setupStep6Body": "Appuyez sur « Afficher le QR d'installation » et scannez-le avec le téléphone, puis créez un code d'appairage et saisissez-le là-bas. Un code est valable cinq minutes.",
  "mobile.setupOpenSettings": "Ouvrir les réglages Mobile",
  "settings.usageStats": "Statistiques d'utilisation",
  "settings.pdfMarkup": "Annotation de PDF",
  "settings.pdfMarkupHelp": "Ce que Annoter du lecteur PDF envoie à l’agent. Conservé sur cet ordinateur ; le téléphone a le sien (Accueil → Ce téléphone → Prompt d’annotation).",
  "settings.pdfMarkupInstruction": "Prompt d’annotation",
  "settings.pdfMarkupInstructionHelp": "Placé après le fichier, la copie annotée, les calques et vos notes à chaque envoi. Avec « Appliquer les annotations directement », l’agent fait par défaut les changements et recompile le PDF ; sinon — ou là où aucune annulation ne peut être gardée — il liste les changements et ne modifie rien avant votre accord.",
  "settings.pdfMarkupApply": "Prompt « Appliquer ces changements »",
  "settings.pdfMarkupApplyHelp": "Envoyé par le bouton Appliquer ces changements une fois que l’agent a listé ce que demandent vos annotations.",
  "settings.pdfMarkupAutoReload": "Recharger le PDF sous vos annotations quand il change",
  "settings.pdfMarkupAutoReloadHelp": "Quand l’agent recompile un PDF que vous annotez, ses nouvelles pages apparaissent d’elles-mêmes sous vos annotations. Désactivé : la barre d’annotation propose Recharger le PDF.",
  "settings.pdfMarkupSubagents": "Confier chaque envoi à un nouveau sous-agent",
  "settings.pdfMarkupSubagentsHelp": "Chaque envoi demande à l’agent de confier la passe à un nouveau sous-agent à lui et d’être libre aussitôt, pour que la passe suivante parte sans attendre — les passes avancent en parallèle. Pour les agents qui peuvent lancer des sous-agents (Claude Code) ; un agent qui ne le peut pas fait la passe lui-même.",
  "settings.pdfMarkupDirect": "Appliquer les annotations directement",
  "settings.pdfMarkupDirectHelp": "À l’envoi, l’agent fait les changements tout de suite ; une fois qu’il a fini, Annuler remet chaque fichier modifié par la série dans son état d’avant — et refuse plutôt que d’écraser ce qui a changé depuis. Là où aucune annulation ne peut être gardée (pas un dépôt git, trop de fichiers non suivis, …), ou si c’est désactivé, l’agent liste d’abord les changements et « Appliquer ces changements » les lui fait faire.",
  "settings.pdfMarkupReset": "Utiliser la valeur par défaut",
  "markup.ask.label": "Questions sur vos annotations",
  "markup.ask.help": "À quelle fréquence l’agent vous interroge sur une annotation avant de lister les changements. Ajouté après le prompt d’annotation à chaque envoi.",
  "markup.ask.stop0": "Toujours demander",
  "markup.ask.stop1": "Demander souvent",
  "markup.ask.stop2": "Demander en cas de doute",
  "markup.ask.stop3": "Demander rarement",
  "markup.ask.stop4": "Ne jamais demander",
  "markup.ask.hint0": "Une question pour chaque annotation avant qu’elle compte comme changement.",
  "markup.ask.hint1": "Demande dès qu’une annotation laisse un choix.",
  "markup.ask.hint2": "Demande seulement pour les annotations illisibles ou les vrais choix ; sinon prend la lecture évidente.",
  "markup.ask.hint3": "Demande seulement s’il ne peut pas du tout agir sans votre réponse.",
  "markup.ask.hint4": "Tranche lui-même chaque annotation ambiguë et liste ce qu’il a décidé.",
  "settings.dailyRecap": "Afficher le récapitulatif au début de chaque journée",
  "settings.openUsageStats": "Ouvrir les statistiques d'utilisation",

