  "updates.help": "{app} consulte la page des releases GitHub du projet — uniquement quand tu le demandes. Rien n’est téléchargé avant un clic, et le redémarrage reste le tien.",
  "brand.tagline": "Un onglet pour chaque projet. Un onglet pour tout ce qu’il contient.",
  "updates.installedVersion": "Version installée",
  "updates.checking": "Vérification…",
  "updates.checkNow": "Vérifier maintenant",
  "updates.upToDate": "{app} est à jour.",
  "updates.legacyTitle": "Noms d’avant le changement de nom",
  "updates.legacyHelp": "{app} a changé de nom. Ce qu’une version précédente a enregistré sous l’ancien nom est repris, et chaque fois que quelque chose n’est encore trouvé que sous l’ancien nom, c’est compté ici. Quand cette liste reste vide sur toutes vos machines, l’ancien nom n’est plus nécessaire nulle part.",
  "updates.legacyNone": "Rien n’a été trouvé sous l’ancien nom.",
  "updates.legacyHit": "{id} : {count} fois, la dernière le {last}",
  "updates.legacyUnfinished": "Pas encore repris :",
  "updates.versionAvailable": "La version {version} est disponible",
  "updates.noAssetForPlatform": "Cette release ne publie aucun téléchargement pour ta plateforme. Ouvre la page de la release pour voir ce qu’elle contient.",
  "updates.downloading": "Téléchargement…",
