  "updates.installerLaunched": "L’installateur est lancé — suis ses étapes.",
  "updates.restartToApply": "Installé. Redémarre {app} pour utiliser la nouvelle version.",
  "updates.savedTo": "Enregistré dans {path}",
  "updates.openReleasePage": "Ouvrir la page de la release",
  "updates.installAppimageHelp": "Installer remplace l’AppImage en cours d’exécution. Tes onglets et terminaux restent ouverts — redémarre {app} quand cela t’arrange.",
  "updates.installNsisHelp": "Installer lance l’installateur Windows, qui propose d’abord de fermer {app}.",
  "updates.installDmgHelp": "Installer ouvre l’image disque — glisse {app} dans Applications depuis là.",
  "updates.installManualHelp": "Cette copie de {app} a été installée par un gestionnaire de paquets ; le téléchargement te revient donc à installer toi-même.",
  "settings.energyUnavailable": "État d'alimentation indisponible — traité comme sur secteur (inactif).",
  "settings.energyActiveAlways": "Actuellement actif — toujours activé.",
  "settings.energyActiveBattery": "Actuellement actif — fonctionne sur batterie.",
  "settings.energyOff": "Désactivé — ne ralentit jamais.",
  "settings.energyInactive": "Inactif — sur secteur.",
  "settings.claudeRemoteHelp1": "Lance des onglets d'agent Claude avec",
  "settings.claudeRemoteHelp2": "afin que vous puissiez les surveiller et les piloter depuis l'application ou le web Claude. Nécessite une connexion par abonnement Claude (pas une clé API) ; seul Claude le prend en charge.",
  "settings.headlessRemoteHelp": "Lorsque c'est activé (par défaut), {app} établit les connexions SSH/OpenVPN en arrière-plan, en gérant le mot de passe de façon transitoire. Désactivez-le pour ouvrir plutôt chaque connexion comme un terminal interactif dans la racine de {app} — vous tapez le mot de passe directement dans ce terminal et {app} ne le manipule jamais.",
  "settings.persistLocalHelp1": "Lorsque c'est activé (par défaut), le shell et les onglets Python/script d'un projet local s'exécutent dans une session tmux sur cette machine, afin qu'une longue exécution continue si {app} plante, et l'onglet se rattache au redémarrage. Fermer un onglet met quand même fin à sa session. Nécessite",
  "settings.persistLocalHelp2": " ; les onglets d'agent ne sont pas concernés.",
  "settings.remoteFeaturesHelp": "Les deux ajoutent un contrôle à l'échelle de la machine dans l'en-tête : un tunnel OpenVPN (redirige le trafic de tout cet ordinateur tant qu'il est actif) et une liste de machines SSH qu'aucun projet ne possède. Désactivé par défaut ; demandé une fois au premier lancement.",
  "settings.energyHelp": "Lorsque c'est actif, {app} se relâche pour économiser l'énergie : il met en pause la rotation au repos du blob de projet, calme les lueurs de statut et ralentit les actualisations en arrière-plan. « Sur batterie » (par défaut) ne le fait que lorsque débranché.",
  "settings.fastModeHelp": "Abandonne les aides qui coûtent du vrai travail : les tailles de dossier dans l'arborescence, les points git sur les pastilles de projet, les cartes au survol, l'affichage CPU/RAM dans l'en-tête, la vérification Exécuter de Python et les animations de l'interface. Rien n'est masqué et rien n'est perdu sans être enregistré — {app} en dit moins, plus tôt. Utile sur un disque lent, une machine chargée ou un projet distant sur un lien étroit.",
  "settings.experimentalHelp1": "Fonctionnalités encore en mouvement. Chacune est désactivée par défaut et",
  "settings.experimentalHelpBold": "activée par défaut en mode débogage",
  "settings.experimentalHelp2": "— ainsi, compiler {app} signifie les voir sans devoir recocher cette liste à chaque nouvelle arrivée. Un interrupteur ici l'emporte toujours, dans les deux sens : vous pouvez en activer une sans le mode débogage, ou en désactiver une tout en y étant.",
  "settings.experimentalHelp3": "Désactiver une fonctionnalité qui possède son propre onglet (Courrier, Navigateur) ferme aussi les onglets qu'elle a ouverts — désactivé veut dire parti, pas seulement masqué du menu de nouvel onglet.",
  "settings.pythonRunHelp1": "Donne à un fichier",
  "settings.pythonRunHelp2": "ouvert dans l'éditeur un bouton",
  "settings.pythonRunHelp3": "et un",
  "settings.pythonRunHelp4": "et transforme ses numéros de ligne en une marge de points d'arrêt. Les deux ouvrent un onglet terminal dans le projet — ils s'exécutent donc sur l'hôte d'un projet distant et dans le conteneur d'un projet conteneurisé — et utilisent le propre interpréteur du projet. Déboguer utilise",
  "settings.pythonRunHelp5": ", préchargé avec les points d'arrêt de la marge. Désactivé par défaut car Exécuter exécute le fichier. Ctrl+clic vers une définition n'est pas verrouillé : il ne fait que lire.",
  "settings.resourceMonitorHelp": "CPU et RAM couvrent l'arborescence de processus propre de {app} ; GPU affiche la VRAM utilisée par les modèles locaux chargés dans Ollama. La pastille apparaît dans l'en-tête à côté du minuteur.",
  "settings.reminderHelp": "Les rappels se déclenchent comme notification de bureau et comme fenêtre contextuelle dans l'app que vous pouvez reporter. « La grille du jour commence à » ne fait que définir jusqu'où défilent les vues jour et semaine — les événements antérieurs sont toujours là, juste au-dessus.",
  "settings.zoomHelp1": "Le zoom de fenêtre redimensionne toute l'interface de {app} — pratique sur les moniteurs 4K / haute densité. 100 % est la valeur par défaut. Le zoom est",
  "settings.zoomHelpBold": "par fenêtre",
  "settings.zoomHelp2": " : cela définit la fenêtre principale, et chaque sous-fenêtre détachée garde le sien. Ctrl + / Ctrl − zooment la fenêtre active et Ctrl 0 le réinitialise.",
  "settings.minSubwindowHelp": "Taille minimale qu'une sous-fenêtre peut atteindre en faisant glisser un séparateur. Par défaut {px}px si laissé vide.",
  "settings.workspaceNoParking": "Ce bureau ne peut pas masquer les fenêtres des autres applications : elles restent à l'écran quand vous changez de projet. {app} masque les applications d'un projet au changement sous X11 avec KDE Plasma et Cinnamon.",
  "settings.downloadsHelp": "Dossiers analysés par la section Téléchargements du panneau latéral (son bouton dans la barre d’outils), pour copier rapidement des fichiers fraîchement téléchargés dans un projet. Lecture seule — {app} ne modifie jamais le chemin de téléchargement d'un navigateur. Par défaut, le dossier Téléchargements du système si vide.",
  "settings.removeFolderTitle": "Supprimer ce dossier",
  "settings.dailyRecapHelp": "Un résumé de la journée qui vient de se terminer : quels agents vous avez utilisés et combien vous les avez sollicités, fichiers créés/modifiés/supprimés, commits et temps par projet. Désactiver ceci arrête la fenêtre contextuelle, pas le comptage — tout reste local.",

