  "steering.agentClear.desc": "Tape /clear dans l'onglet d'agent actif : une nouvelle conversation, que « Annuler l'effacement » sur l'onglet peut reprendre. La navigation {app} reste active.",
  "steering.agentPlan.label": "Plan",
  "steering.agentPlan.desc": "Ouvre la zone de prompt avec /plan au début de la saisie de l'onglet d'agent actif ; tapez la suite, Entrée, et la navigation {app} revient.",
  "steering.agentGoal.label": "Objectif",
