  "steering.jumpProject.label": "Aller au projet",
  "steering.jumpProject.desc": "Saisir le nom d'un projet ouvert ou inactif et appuyer sur Entrée pour y passer ; un projet inactif est activé. La navigation {app} revient ensuite.",
  "steering.popout.label": "Fenêtre détachée",
  "steering.popout.desc": "Amène au premier plan la sous-fenêtre détachée de ce projet pour y travailler ; s'il y en a plusieurs, chaque appui passe à la suivante. La navigation {app} s'arrête quand la fenêtre prend le clavier.",
