  "agentCron.title": "Préchauffage planifié",
  "agentCron.help":
    "À chaque heure ci-dessous, {app} envoie un unique message « {message} » à cet agent en arrière-plan — dans le mode « une seule fois » de la CLI elle-même (claude -p, codex exec, …), sans terminal, onglet ni projet. Le quota d'une CLI d'agent est une fenêtre qui s'ouvre au premier message — cinq heures pour Claude — : ceci décide donc quand la fenêtre commence, au lieu de le laisser au premier vrai prompt tapé.",
  "agentCron.runningNote":
    "Ne se déclenche que si {app} est lancé. Une heure passée alors que l'app est fermée, ou la machine en veille, est ignorée pour ce jour-là et jamais envoyée en retard : l'envoyer des heures après ouvrirait la fenêtre au pire moment.",
