  "agentSchedule.warning": "Lorsqu’un prompt arrive à échéance, {app} attend jusqu’à une heure un point d’inactivité sûr. L’envoi remplace tout texte non envoyé dans l’éditeur de l’agent, même si l’onglet a le focus.",
  "agentSchedule.openOnly": "L’envoi revient à l’{app} en marche : une fenêtre ouverte ou, avec {app} Mobile activé, son service d’arrière-plan tant qu’aucune fenêtre n’est ouverte, qui relance d’abord la session de cet agent si elle s’est arrêtée. Les occurrences manquées sont consignées et les planifications récurrentes n’envoient jamais un arriéré en rafale.",
  "agentSchedule.windowOnlyTimers": "La poursuite automatique, le cron de préchauffage et la synchronisation CalDAV ne s’exécutent toujours que depuis une fenêtre {app} ouverte. Les rappels du calendrier atteignent un téléphone abonné sans fenêtre ouverte, une seule fois.",
