  "pill.containerScopeAgents": "Onglets d'agent uniquement",
  "pill.containerScopeAgentsHelp": "Les shells, les scripts et Exécuter/Déboguer restent sur l'hôte, avec votre chaîne d'outils hôte — un environnement .venv, conda ou pyenv refonctionne, car son interpréteur vit sur l'hôte et non dans l'image.",
  "pill.containerScopeAgentsCaveat": "L'agent écrit toujours dans le dossier du projet : un script qu'il a écrit est à un clic d'Exécuter de toute votre machine. Il ne peut pas franchir ce pas seul — aucun fichier du projet n'est relu comme une commande à lancer — mais lisez ce que vous exécutez. Pour du code que vous jugez hostile et pas seulement non relu, un conteneur est le mauvais niveau.",
