  "pill.vmRebuildTitle": "Reconstruire cette VM ?",
  "pill.vmRebuildConfirm": "Le disque de la VM sera recréé depuis l'image de base. Tout ce qui est dans la VM meurt avec — pour un projet sans miroir, le disque de la VM EST l'arbre de travail ; seul ce qui a été poussé vers un dépôt git (ou téléchargé) survit. Continuer ?",
