  "pill.vmKnobsApplyNote": "Les changements de ressources s'appliquent au prochain démarrage de la VM.",
  "pill.vmEgress": "Sortie réseau",
  "pill.vmEgressProxy": "API des agents uniquement (proxy à liste blanche)",
  "pill.vmEgressOff": "Aucune (totalement fermée)",
  "pill.vmEgressOpen": "Ouverte (réseau complet)",
  "pill.vmEgressProxyCaveat": "La VM n'atteint que les hôtes ci-dessous via le proxy de {app} ; tout le reste est bloqué et journalisé. Limite honnête : un agent peut encore envoyer des données vers les points autorisés (p. ex. dans un prompt) — le proxy rétrécit le canal, il ne peut pas le fermer. Les changements de mode s'appliquent au prochain démarrage.",
  "pill.vmEgressOffNote": "Sans sortie réseau la VM n'atteint rien — les onglets d'agents cloud ne fonctionnent pas ; utilisez un modèle local ou une isolation pure de build/test.",
  "pill.vmMailReader": "Lecteur de courrier",
  "pill.vmMailReaderHelp": "Les onglets d'agent de cette VM peuvent lire les comptes de courrier que vous avez ouverts aux agents, et écrire des brouillons. Sa sortie est restreinte et journalisée, pas scellée : l'agent atteint toujours son propre fournisseur, qui reçoit ce qu'il lit. Il ne peut jamais envoyer — seul un brouillon que vous envoyez vous-même sort. S'applique au prochain démarrage ; pas de miroir, et les fichiers téléchargés depuis cette VM peuvent contenir du courrier.",
  "pill.vmMailReaderWide": "Un lecteur de courrier ne fonctionne qu'avec la sortie Proxy et la liste d'autorisation par défaut — pas de GitHub, pas d'hôtes supplémentaires. Désactivez « Lecteur de courrier » pour élargir le réseau.",
  "pill.vmAllowGithub": "Autoriser github.com (clone/push)",
  "pill.vmAllowHosts": "Hôtes supplémentaires autorisés (un par ligne)",
  "pill.vmAllowHostsPlaceholder": "registry.npmjs.org\n.crates.io",
  "pill.vmBlockedCount": "{count} connexion(s) bloquée(s) — la VM a tenté d'atteindre des hôtes hors liste :",
  "pill.pythonInterpMenuTitle": "L'environnement Python dans lequel les scripts de ce projet s'exécutent et se déboguent. Détecté automatiquement par défaut (venv dans l'arborescence, poetry, conda, pyenv) ; épinglez-en un lorsque votre environnement se trouve là où {app} ne peut pas le déduire.",
  "pill.pythonInterpreterEllipsis": "Interpréteur Python…",
  "pill.autoConnectTitleNonHeadless": "Connecte ce projet tout seul au lancement et lors du passage à celui-ci. {app} ne gère aucun mot de passe dans ce mode, donc la connexion (et le VPN, s'il en a un) s'ouvre dans le terminal racine pour que vous vous authentifiiez — puis le projet se connecte de lui-même.",
  "pill.autoConnectTitleEligible": "Connecte ce projet tout seul au lancement et lors du passage à celui-ci. Il ne demande jamais rien : il entre directement quand l'hôte est accessible, et n'active le VPN que lorsqu'il ne l'est pas.",
  "pill.autoConnectTitleNotEligible": "Enregistrez d'abord le mot de passe SSH (ou utilisez l'authentification par clé) — la connexion automatique n'est proposée que lorsque la connexion ne nécessite rien de vous.",
  "pill.autoConnectOnLaunch": "Connexion automatique au lancement",
  "pill.persistSessionsMenuTitle": "Exécute le shell distant et les onglets Python/script de ce projet dans une session tmux sur l'hôte, afin qu'une longue exécution continue malgré une coupure SSH, une mise en veille du portable ou la fermeture de {app} — l'onglet se rattache à la reconnexion. Fermer un onglet met quand même fin à sa session (avec confirmation). Les onglets d'agent ne sont pas concernés.",
  "pill.persistentSessionsTmux": "Sessions persistantes (tmux)",
  "pill.remoteControlMenuTitle":
    "Indique si les onglets d'agent Claude de ce projet peuvent être surveillés/pilotés depuis l'application ou le web Claude. Cliquez pour parcourir les états : utiliser le réglage global → forcer désactivé → forcer activé.",
  "pill.remoteControlInherit": "Contrôle à distance (par défaut)",
  "pill.remoteControlOff": "Contrôle à distance : désactivé",
  "pill.remoteControlOn": "Contrôle à distance : activé",
  "pill.remoteMachinesMenuTitle": "Ajoutez et gérez des machines supplémentaires sur lesquelles ce projet s'exécute. Elles exécutent le même code (maintenu en synchro unidirectionnelle) en tant que workers d'expérimentation en lecture seule ; leurs sorties restent sur chaque machine.",
  "pill.remoteMachinesCount": "Machines distantes… ({count})",
  "pill.remoteMachinesEllipsis": "Machines distantes…",
  "pill.closeAllTabs": "Fermer tous les onglets et fenêtres",
  "pill.adoptFolderLayout": "Restaurer la disposition enregistrée dans le dossier…",
