  "pill.adoptFolderLayoutNone": "Ce dossier ne contient aucune disposition enregistrée.",
  "pill.dangerZone": "Zone de danger",
  "pill.detachSshMenuTitle": "Retransforme ceci en projet local. La copie de travail locale reste en place et les fichiers de l'hôte distant restent intacts — mais l'appairage est abandonné : la synchronisation Git s'arrête, et la sélection d'auto-synchronisation configurée pour cet hôte est écartée.",
  "pill.detachSshEllipsis": "Détacher l'hôte SSH…",
  "pill.removeGitMenuTitle": "Supprimer le répertoire .git de ce projet et tout l'historique de contrôle de version (irréversible)",
  "pill.removeGitHistoryEllipsis": "Supprimer git et l'historique…",
  "pill.deleteProjectMenuTitle": "Déconnectez ce projet et déplacez-le vers l'archive {app}. Restaurez-le ou supprimez-le définitivement plus tard depuis les Paramètres. Les fichiers d'un hôte distant ne sont jamais touchés.",
  "pill.deleteProjectEllipsis": "Supprimer le projet…",
  "pill.forgetProjectMenuTitle": "Retire ce projet de {app} mais laisse son dossier exactement là où il est. Rien dans le dossier n'est touché : seuls les enregistrements propres à {app} concernant le projet disparaissent. Vous pourrez réimporter le dossier ensuite.",
  "pill.forgetProjectEllipsis": "Retirer de {app}…",
