  "remoteConnect.autoConnectVpnWarningStrong": "sans demander",
  "remoteConnect.autoConnectVpnWarningPost": "— redirigeant le trafic de cet ordinateur au démarrage. L'indicateur VPN de l'en-tête montre quand un tunnel est actif, et peut le couper.",
  "remoteConnect.autoConnectInteractiveTitle": "Connecte ce projet tout seul au démarrage et lors du basculement vers lui. {app} ne gère aucun mot de passe dans ce mode, donc la connexion (et le VPN, si ce projet en a un) s'ouvre dans le terminal racine pour que vous vous authentifiiez — le projet se connecte de lui-même une fois que vous êtes connecté.",
  "remoteConnect.autoConnectInteractiveHint": "au démarrage et au basculement — ouvre la connexion dans le terminal racine",
