  "remoteMachines.introPre": "Toutes les machines que ce projet atteint, au même endroit — la",
  "remoteMachines.introStrongPrimary": "principale",
  "remoteMachines.introMid1": "qui possède ses fichiers et git, plus toute machine worker supplémentaire qui exécute son",
  "remoteMachines.introStrongSameCode": "même code",
  "remoteMachines.introMid2": ". Connectez ou gérez l'une d'elles ici, ou ajoutez un nouveau worker ci-dessous. Un nouveau worker partage par défaut le dossier du projet de la machine principale (pas de copie, pas de git) ; cochez",
  "remoteMachines.introStrongSyncCopy": "Synchroniser une copie",
