  "remoteMachines.saveTitleTerminal": "{app} ne voit jamais une connexion en terminal, donc rien de nouveau n'est stocké — et rien n'est supprimé non plus. Tout mot de passe enregistré reste tel quel ; c'est dans le menu Connecter propre à la machine que vous le modifiez.",
  "remoteMachines.saveTitleHeadless": "Enregistre le mot de passe SSH de cette machine dans le trousseau de votre système, indexé par hôte — le menu Connecter propre à la machine le retrouve alors et ne redemande plus. Désactivé par défaut ; décocher supprime un mot de passe précédemment enregistré.",
