  "carefulHost.hintHpcTagged": "toujours actif : cette machine est étiquetée comme nœud de connexion d'un cluster HPC",
  "hpcHost.title": "Étiquette cette machine comme un nœud de connexion de cluster partagé. {app} ne scanne ni ne mesure alors plus jamais son système de fichiers par elle-même, n'exécute aucune synchronisation de fichiers ou Git en arrière-plan contre elle, ne s'y connecte jamais silencieusement au lancement, la lit légèrement quel que soit l'état de l'interrupteur de lecture, et demande avant qu'une exécution n'y atterrisse. Rien ne détecte cela — qu'un ordonnanceur soit dans le PATH indique que la machine dispose de SLURM, pas que ses opérateurs y consentent.",
  "hpcHost.label": "Cluster HPC (nœud de connexion)",
  "hpcHost.hintOn": "travail en arrière-plan désactivé, lecture légère forcée, les exécutions demandent confirmation d'abord",
