  "savePassword.titleTerminal": "Une connexion par terminal est quelque chose que {app} ne voit jamais, donc rien de nouveau n'est enregistré — et rien n'est supprimé non plus. Tout mot de passe déjà enregistré pour cet hôte reste inchangé.",
