  "autoConnect.offWhileHpc": "— désactivé tant qu'elle est étiquetée HPC",
  "autoConnect.hpcTitle": "Cette machine est étiquetée comme nœud de connexion d'un cluster HPC, donc {app} ne s'y connecte jamais d'elle-même. Retirez l'étiquette pour activer ceci.",
