  "machines.autoConnectAddTitle": "Connecte cette machine silencieusement au lancement de {app} et chaque fois qu'un tunnel VPN s'active. Ne demande jamais — ne se connecte que lorsque l'hôte est accessible sans mot de passe, donc une machine armée qui ne peut pas se connecter silencieusement reste simplement inactive.",
