  "machines.hpcToggleTitle": "Étiquette cette machine comme un nœud de connexion de cluster partagé. {app} la lit alors légèrement (aucun nom ni commande d'autres utilisateurs), ne scanne ni ne mesure jamais son système de fichiers par elle-même, n'exécute jamais de synchronisation de fichiers ou Git en arrière-plan contre elle, ne la vérifie ni ne s'y connecte sauf si vous le demandez, et demande avant que quoi que ce soit ne s'exécute dans son shell de nœud de connexion. L'étiqueter efface aussi sa connexion au lancement.",
  "machines.hpcAddTitle": "Étiquette cette machine comme un nœud de connexion de cluster partagé. {app} la lit alors légèrement (jamais de noms ni de lignes de commande d'autres utilisateurs), ne scanne ni ne mesure jamais son système de fichiers par elle-même, n'exécute aucune synchronisation de fichiers ou Git en arrière-plan contre elle, ne la vérifie ni ne s'y connecte sauf si vous le demandez, et demande avant que quoi que ce soit ne s'exécute dans son shell de nœud de connexion.",
  "machines.hpcBadgeTitle": "Étiquetée comme nœud de connexion de cluster partagé : lecture légère, aucun scan d'utilisation disque ni recensement de dossiers, aucune synchronisation de fichiers ou Git en arrière-plan, aucune vérification automatique d'accessibilité, aucune connexion automatique silencieuse, et un avertissement avant que quoi que ce soit ne s'exécute dans un shell de nœud de connexion.",
