  "caldav.allowWrite": "Envoyer mes modifications \u00E0 ce serveur",
  "caldav.requireVpn": "Se connecter uniquement quand le VPN est actif",
  "caldav.requireVpnHint": "Pour un serveur de calendrier accessible uniquement depuis l'intérieur de son réseau. Tant qu'aucun tunnel OpenVPN n'est monté, ce compte est ignoré au lieu d'échouer, puis synchronisé dès qu'un tunnel s'ouvre. Seuls les tunnels lancés depuis {app} comptent.",
  "caldav.allowWriteHint": "D\u00E9sactiv\u00E9 par d\u00E9faut. Tant que c'est d\u00E9sactiv\u00E9, les agendas de ce compte sont en lecture seule ici : rien n'est envoy\u00E9, et rien n'est retenu en silence. Une fois activ\u00E9, les modifications, les nouvelles entr\u00E9es et les suppressions atteignent le serveur. Un agenda que le serveur signale en lecture seule pour votre compte le reste dans tous les cas.",
  "caldavConflict.title": "Modifi\u00E9 ailleurs aussi",
  "caldavConflict.ledeEdit": "Votre modification de \u00AB\u00A0{title}\u00A0\u00BB n'a pas \u00E9t\u00E9 envoy\u00E9e au serveur.",
