  "mail.encryption.offerIntro": "Chiffrer le courrier que {app} conserve sur cette machine, afin que ses messages, pièces jointes et brouillons soient illisibles sans la clé.",
  "mail.encryption.scopeHonest": "Ce que cela protège réellement : les sauvegardes, les copies, les dossiers synchronisés vers un nuage et les machines auxquelles d'autres personnes peuvent se connecter. Cela ne protège pas de quelqu'un capable d'exécuter des programmes sous votre compte pendant que {app} est ouvert, et si votre disque est déjà chiffré, l'apport face à un portable volé est faible.",
  "mail.encryption.metadataHonest": "Restent lisibles sur le disque : le nombre de messages, les dossiers existants, ainsi que la date, la taille et l'état lu/suivi de chaque message. Les masquer demande un chiffrement de disque complet, qui masque aussi les noms de fichiers.",
