  "mail.agentAccessHint": "Seuls un agent lecteur confiné (un agent dans un projet VM marqué « lecteur de courrier ») et, si les réglages le permettent, un onglet de modèle local peuvent lire — ce dernier seulement les messages que vous partagez. Ce que lit un agent lecteur confiné est envoyé à son fournisseur. Aucun agent ne peut envoyer, marquer, déplacer ni supprimer. Les agents cloud de la console racine ne lisent jamais le courrier ; ils ne peuvent qu'écrire des brouillons, quel que soit ce réglage.",
