  "pill.agentFenceMenuTitle": "Chaque onglet d'agent local de ce projet s'exécute dans le bac à sable, dans le dossier d'agent propre au projet ; il n'y a pas d'interrupteur. Le travail hors du bac à sable, c'est la session hôte de la console racine.",
