  "pill.agentFenceGlyphLive": "{count} onglet(s) d'agent de ce projet tournent hors du bac à sable — lancés avant qu'il devienne le seul mode. Fermez-les et rouvrez-les pour les y placer.",
  "pill.agentFenceLiveUnfenced": " · {count} onglet(s) en cours hors du bac à sable — fermez-les et rouvrez-les",
  "common.on": "activé",
  "common.off": "désactivé",
  "hpcGuard.duScan.title": "Analyser toute l’arborescence sur un cluster ?",
  "hpcGuard.duScan.body": "Cette action parcourt chaque fichier sous la racine du projet pour additionner les tailles. Sur un cluster, cette racine se trouve normalement sur le système de fichiers parallèle, où un parcours récursif signifie une requête de métadonnées par fichier vers un serveur partagé par tout le site — ce que les guides du système de fichiers demandent d’éviter à la légère. C’est une seule analyse, pas une boucle : elle vous revient si vous la voulez.",
  "hpcGuard.duScan.go": "Analyser quand même",
  "hpcGuard.census.title": "Mesurer les dossiers de l’hôte sur un cluster ?",
  "hpcGuard.census.body": "Le recensement des dossiers géants exécute `du` sur toute l’arborescence de l’hôte pour trouver ce qui est trop gros à synchroniser. Même coût en métadonnées qu’une analyse complète, et celui-ci se lance normalement tout seul à la connexion — c’est pourquoi il reste désactivé ici sauf demande explicite.",
  "hpcGuard.census.go": "Mesurer quand même",
  "hpcGuard.connect.title": "Se connecter à ce cluster ?",
  "hpcGuard.connect.body": "Ouvrir cet onglet composerait le numéro de la machine et y laisserait un maître SSH partagé (et, pour un onglet persistant, un serveur tmux avec lui) — la présence non surveillée que l’étiquette existe pour empêcher. C’est juste pour un onglet restauré au redémarrage, que personne n’a demandé ; cela ne gêne que lorsque vous vouliez vraiment en ouvrir un. Continuer connecte d’abord le projet, puis ouvre l’onglet.",
  "hpcGuard.connect.go": "Connecter et ouvrir",
  "hpcGuard.loginNodeRun.title": "Exécuter ceci sur le nœud de connexion ?",
  "hpcGuard.loginNodeRun.body": "Ceci s’exécuterait sur le nœud de connexion du cluster, partagé avec toutes les personnes connectées en ce moment. Les centres demandent d’en écarter les travaux gourmands en CPU et se réservent le droit de tuer les processus qui le chargent longtemps. La voie conforme pour le même travail est une tâche interactive — le shell srun de la vue Tâches — ou un script batch avec sbatch.",
  "hpcGuard.loginNodeRun.go": "Exécuter ici quand même",
  "hpcGuard.note": "Vous avez étiqueté cette machine comme nœud de connexion d’un cluster. Retirez l’étiquette dans le menu Machines si c’était une erreur — rien n’est mémorisé ici, la question sera donc reposée la prochaine fois.",
  "unfencedPlatform.title": "Les agents sur cet ordinateur s'exécutent avec tous vos droits",
  "unfencedPlatform.body": "Windows n'a pas de bac à sable pour les agents. Un agent lancé ici peut lire et modifier tout ce que votre compte peut : autres projets, mots de passe enregistrés, clés SSH, profil du navigateur. Sous Linux et macOS, {app} garde les agents dans un bac à sable limité à leur projet ; ici, il ne le peut pas.",
  "unfencedPlatform.alternative": "Acceptez pour lancer des agents sur cet ordinateur désormais — {app} ne demande qu'une fois. Vous préférez une limite ? Ouvrez plutôt le projet dans un conteneur.",
  "unfencedPlatform.accept": "Accepter et lancer",
  "unfencedPlatform.declined": "Non lancé : les agents sur cet ordinateur s'exécutent avec tous vos droits, et cela n'a pas été accepté. Ouvrez un nouvel onglet d'agent pour être redemandé, ou ouvrez le projet dans un conteneur.",
  "passwordInput.show": "Afficher le mot de passe",
  "passwordInput.hide": "Masquer le mot de passe",
