  "rootConsole.rightsBadge": "⚿ Outils {app}",
  "rootConsole.rightsLocalOnly": "Seuls les onglets de modèles locaux ouverts ici reçoivent les outils propres à {app} (MCP) : vos projets, le calendrier et le tableau des tâches. Les agents cloud et ceux d'un projet ne les reçoivent pas.",
  "rootConsole.rightsOn": "Les agents ouverts ici reçoivent les outils propres à {app} (MCP) : vos projets, le calendrier et le tableau des tâches. Les agents d'un projet ne les reçoivent pas.",
  "rootConsole.rightsOff": "Les outils de {app} ne sont pas lancés : les agents ouverts ici sont des agents ordinaires jusqu'au redémarrage de {app}.",
