  "rootConsole.rightsInSettings": "Ce qu'un onglet racine peut faire avec ces outils s'active et se désactive dans les Paramètres.",
  "rootConsole.noPhone": "La console racine n'est jamais proposée à {app} Mobile ni au contrôle à distance de Claude.",
  "rootConsole.mailOpen": "Au moins un compte de courrier partage des messages marqués avec des agents qui lisent le courrier : un agent lecteur confiné ou, si les réglages le permettent, un onglet de modèle local. Les onglets racine cloud ne lisent toujours aucun courrier ; ils ne peuvent qu'écrire des brouillons.",
  "rootConsole.mailOpenAll": "Au moins un compte de courrier est entièrement ouvert à un agent lecteur confiné ; un onglet de modèle local, si les réglages le permettent, ne voit toujours que les messages marqués. Les onglets racine cloud ne lisent toujours aucun courrier ; ils ne peuvent qu'écrire des brouillons.",
  "rootConsole.reviewAdvisory": "La relecture n'est pas imposée : les agents racine tournent sans le bac à sable des agents, un agent peut donc modifier le calendrier, le tableau ou ce réglage directement, sans proposition. Activez le bac à sable pour que la relecture soit une barrière.",
